sysauto_script.script:
(function() {
    var today = new GlideDateTime();
    var futureDate = new GlideDateTime();
    futureDate.addDaysUTC(90);

    var gr = new GlideRecord('x_848842_techdesk_asset');
    gr.addQuery('depreciation_end', '>=', today.getDate().toString());
    gr.addQuery('depreciation_end', '<=', futureDate.getDate().toString());
    gr.addQuery('lifecycle_state', 'deployed');
    gr.query();

    while (gr.next()) {
        var displayName = gr.getValue('display_name');

        var request = new GlideRecord('x_848842_techdesk_request');
        request.initialize();
        request.setValue('request_type', 'hardware');
        request.setValue('short_description', 'Hardware Refresh - ' + displayName);
        request.setValue('state', 'draft');
        request.setValue('priority', '3');
        request.insert();

        gs.info('TechDesk Depreciation Alert: Created hardware refresh request for asset ' + displayName);
    }
})();
